const normalize=value=>String(value??'').trim().toLowerCase().replace(/\s+/g,' ').replace(/[ًٌٍَُِّْـ]/g,'');
const readJson=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key)||'null')??fallback;}catch{return fallback;}};
const writeJson=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
const uid=prefix=>`${prefix}-${Date.now().toString(36)}-${globalThis.crypto?.randomUUID?.().replaceAll('-','').slice(0,12)||Math.random().toString(36).slice(2,14)}`;
const bytesToB64Url=bytes=>{let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,Math.min(i+0x8000,bytes.length)));return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');};
const b64UrlToBytes=value=>{const text=String(value||'').replace(/-/g,'+').replace(/_/g,'/'),padded=text+'='.repeat((4-text.length%4)%4),binary=atob(padded);return Uint8Array.from(binary,ch=>ch.charCodeAt(0));};
const b64ToBytes=value=>Uint8Array.from(atob(value),ch=>ch.charCodeAt(0));
function addDays(value,days){const d=dateOnly(value);d.setDate(d.getDate()+Number(days||0));return iso(d);}
function isDynamicMonthly(student){return Boolean(student?.snapshot?.dynamicMonthly||student?.snapshot?.centerOpsMonthlyV11);}
function isNewModel(student){return Boolean(student?.snapshot?.centerOpsV11||isDynamicMonthly(student));}
