let expenses=Array.isArray(readJson(STORAGE.expenses,[]))?readJson(STORAGE.expenses,[]):[];
let methodRecords=Array.isArray(readJson(STORAGE.methods,[]))?readJson(STORAGE.methods,[]):[];
let securityState=readJson(STORAGE.security,{users:[]});
if(!securityState||typeof securityState!=='object')securityState={users:[]};
if(!Array.isArray(securityState.users))securityState.users=[];

function normalizeExpenses(){expenses=expenses.filter(item=>item&&Number(item.amount)>0&&item.branch&&item.specialty).map(item=>({id:String(item.id||uid('expense')),name:String(item.name||'مصروف').trim(),amount:Math.max(0,Number(item.amount||0)),method:String(item.method||'').trim(),branch:String(item.branch),specialty:String(item.specialty),date:String(item.date||today()),time:String(item.time||'00:00'),createdAt:Number(item.createdAt||Date.now())}));writeJson(STORAGE.expenses,expenses);}
