function syncActiveMethods(){normalizeMethodRecords();const active=methodRecords.filter(x=>x.active).map(x=>x.name);methods.splice(0,methods.length,...active);localStorage.setItem('efc-payment-methods-v1',JSON.stringify(active));writeJson(STORAGE.methods,methodRecords);}
normalizeExpenses();syncActiveMethods();

// Extra Center Ops state remains locally available at all times and is injected into
// explicit backup/restore persistence. There is one wrapper only, installed here once.
const baseForcePersist=window.EFC_FORCE_PERSIST;
const baseApplyRestored=window.EFC_APPLY_RESTORED_STATE;
let extraSaveTimer=null;
async function persistExtrasNow(){if(typeof baseForcePersist!=='function')return null;const state=await baseForcePersist();state.expenses=expenses;state.paymentMethodRecords=methodRecords;state.security=securityState;if(invoke)await invoke('save_app_state',{state:JSON.stringify(state)});return state;}
function persistExtrasSoon(){clearTimeout(extraSaveTimer);extraSaveTimer=setTimeout(()=>persistExtrasNow().catch(error=>console.error('EFC extras save failed',error)),350);}
if(typeof baseForcePersist==='function')window.EFC_FORCE_PERSIST=async()=>await persistExtrasNow()||baseForcePersist();
if(typeof baseApplyRestored==='function')window.EFC_APPLY_RESTORED_STATE=async incoming=>{const result=await baseApplyRestored(incoming);if(Array.isArray(incoming?.expenses)){expenses=incoming.expenses;normalizeExpenses();}if(Array.isArray(incoming?.paymentMethodRecords)){methodRecords=incoming.paymentMethodRecords;syncActiveMethods();}if(incoming?.security&&typeof incoming.security==='object'){securityState=incoming.security;writeJson(STORAGE.security,securityState);}persistExtrasSoon();return result;};

const legacyRemainingOf=remainingOf,legacyCourseStatus=courseStatus,legacyFinancialStatus=financialStatus;
const legacyInstallmentPlan=typeof installmentPlanV3==='function'?installmentPlanV3:null;
const legacyMonthlyFocus=typeof monthlyFocusV3==='function'?monthlyFocusV3:null;
const legacyDueNow=typeof dueNowV3==='function'?dueNowV3:null;
const legacySuggested=typeof suggestedPaymentV3==='function'?suggestedPaymentV3:null;
const legacyAlloc=typeof allocV4==='function'?allocV4:null;

function visibleMonthCount(student,asOf=today()){
  if(!isDynamicMonthly(student))return 0;
  if(isInactive(student))return Math.max(0,Number(student.frozenMonths||0));
  if(!student.start)return 0;
  let count=1;
  for(let n=2;n<=240;n++){const due=addDuration(student.start,n-1,'month');if(asOf>=addDays(due,-3))count=n;else break;}
  return count;
}
function dynamicAllocation(student,asOf=today(),paidOverride=null){
  const count=visibleMonthCount(student,asOf),fee=Math.max(0,Number(student.snapshot?.fee||0)),monthPaid=Array(count).fill(0),allocations=[];
  const place=(paymentIndex,monthIndex,amount)=>{if(monthIndex<0||monthIndex>=count||amount<=0)return 0;const room=Math.max(0,fee-monthPaid[monthIndex]),used=Math.min(room,amount);if(used>0){monthPaid[monthIndex]+=used;allocations.push({paymentIndex,monthNumber:monthIndex+1,amount:used});}return used;};
  if(paidOverride!==null&&paidOverride!==undefined){let left=Math.max(0,Number(paidOverride||0));for(let i=0;i<count&&left>0;i++)left-=place(-1,i,left);return{monthPaid,allocations};}
  (student.payments||[]).forEach((payment,index)=>{if(asOf&&String(payment?.[0]||'')>asOf)return;let left=Math.max(0,Number(payment?.[1]||0));const target=Number(payment?.[7]||0);if(Number.isInteger(target)&&target>=1&&target<=count)left-=place(index,target-1,left);for(let i=0;i<count&&left>0;i++)left-=place(index,i,left);});
  return{monthPaid,allocations};
}
installmentPlanV3=function(student,asOf=today(),paidOverride=null){if(!isDynamicMonthly(student))return legacyInstallmentPlan?legacyInstallmentPlan(student,asOf,paidOverride):[];const fee=Math.max(0,Number(student.snapshot?.fee||0)),count=visibleMonthCount(student,asOf),{monthPaid}=dynamicAllocation(student,asOf,paidOverride);return Array.from({length:count},(_,i)=>{const number=i+1,dueDate=addDuration(student.start,i,'month'),paid=Math.min(fee,Number(monthPaid[i]||0)),remaining=Math.max(0,fee-paid);let state='upcoming';if(!remaining)state='paid';else if(paid>0)state='partial';else if(dueDate<asOf)state='overdue';else if(asOf>=addDays(dueDate,-3))state='due';return{number,dueDate,fee,paid,remaining,state};});};
remainingOf=function(student){if(!isDynamicMonthly(student))return legacyRemainingOf(student);const plan=installmentPlanV3(student);student.required=plan.reduce((s,m)=>s+Number(m.fee||0),0);return plan.reduce((s,m)=>s+Number(m.remaining||0),0);};
monthlyFocusV3=function(student,asOf=today(),paidOverride=null){if(!isDynamicMonthly(student))return legacyMonthlyFocus?legacyMonthlyFocus(student,asOf,paidOverride):null;const plan=installmentPlanV3(student,asOf,paidOverride),first=plan.find(m=>m.remaining>0);if(!plan.length)return null;if(!first){const last=plan.at(-1);return{state:'complete',number:last.number,label:`الشهر ${last.number} مدفوع كامل`,dueAmount:0,dueDate:last.dueDate,plan};}const labels={partial:'دفع جزئي',overdue:'متأخر',due:'مستحق',upcoming:'لم يحن'};return{state:first.state,number:first.number,label:`الشهر ${first.number} ${labels[first.state]||'مستحق'}`,dueAmount:['partial','overdue','due'].includes(first.state)?first.remaining:0,dueDate:first.dueDate,plan};};
financialStatus=function(student){if(isDynamicMonthly(student)){const f=monthlyFocusV3(student);if(!f)return remainingOf(student)>0?'لم يدفع':'مدفوع كامل';return f.state==='complete'?'مدفوع كامل':f.state==='partial'?'دفع جزئي':f.state==='overdue'?'متأخر':f.state==='due'?'مستحق الآن':'لم يدفع';}return legacyFinancialStatus(student);};
courseStatus=function(student){if(isInactive(student))return'موقوف';if(isDynamicMonthly(student))return'نشطة';return legacyCourseStatus(student);};
monthBadgeV3=function(student,asOf=today(),paidOverride=null){const f=monthlyFocusV3(student,asOf,paidOverride);if(!f)return'';return`<span class="badge ${f.state==='complete'?'good':f.state==='overdue'?'bad':f.state==='upcoming'?'neutral':'warn'}">${esc(f.label)}</span>`;};
dueNowV3=function(student){if(!isDynamicMonthly(student))return legacyDueNow?legacyDueNow(student):remainingOf(student);const f=monthlyFocusV3(student);return['partial','due','overdue'].includes(f?.state)?Number(f.dueAmount||0):0;};
