allocV4=function(student,paymentIndex){if(!isDynamicMonthly(student))return legacyAlloc?legacyAlloc(student,paymentIndex):{desc:'',before:0,after:0,months:[]};const payment=student.payments?.[paymentIndex];if(!payment)return{desc:'',before:0,after:0,months:[]};let before=0;for(let i=0;i<paymentIndex;i++)before+=Number(student.payments?.[i]?.[1]||0);const amount=Number(payment[1]||0),alloc=dynamicAllocation(student),months=alloc.allocations.filter(x=>x.paymentIndex===paymentIndex).map(x=>({n:x.monthNumber,amount:x.amount})),numbers=[...new Set(months.map(x=>x.n))],name=spec(student.specialty)?.name||'الدورة';return{desc:numbers.length?`دفعة للشهر ${numbers.join('، ')} لدورة ${name}`:`دفعة لدورة ${name}`,before,after:before+amount,months};};

