let bellTimer=null;
function refreshBellSoon(){clearTimeout(bellTimer);bellTimer=setTimeout(refreshBell,80);}
function debtMessage(student,amount,due,overdue=false){return overdue?`عزيزي الطالب ${student.name}، نذكرك بأن عليك مبلغًا متبقيًا قدره ${cash(amount)}، وقد كان موعد سداده بتاريخ ${showDate(due)}. يرجى تسديده في أقرب وقت.`:`عزيزي الطالب ${student.name}، نذكرك بأن عليك مبلغًا متبقيًا قدره ${cash(amount)}، وموعد سداده ${due===addDays(today(),1)?'غدًا ':''}${showDate(due)}.`;}
function notificationsForStudent(student){if(!student||isInactive(student))return[];const out=[],asOf=today();if(isDynamicMonthly(student)){installmentPlanV3(student,asOf).forEach(month=>{if(month.remaining<=0)return;const custom=student.debtDueDates?.[String(month.number)];if(custom&&asOf>=addDays(custom,-1)){out.push({studentId:student.id,studentName:student.name,message:debtMessage(student,month.remaining,custom,asOf>custom)});return;}const opens=addDays(month.dueDate,-3);if(asOf>=opens&&asOf<month.dueDate)out.push({studentId:student.id,studentName:student.name,message:`عزيزي الطالب ${student.name}، نذكرك بأن اشتراكك الشهري سينتهي بتاريخ ${showDate(month.dueDate)}، وقيمة تجديد الشهر القادم ${cash(month.fee)}.`});else if(asOf>=month.dueDate)out.push({studentId:student.id,studentName:student.name,message:`عزيزي الطالب ${student.name}، نذكرك بأن مبلغ الشهر ${month.number} وقدره ${cash(month.remaining)} مستحق للسداد.`});});}else if(isNewModel(student)&&remainingOf(student)>0){const due=student.debtDueDates?.course;if(due&&asOf>=addDays(due,-1))out.push({studentId:student.id,studentName:student.name,message:debtMessage(student,remainingOf(student),due,asOf>due)});}return out;}
function currentNotifications(){if(securityState.users.length&&!canView('students'))return[];return students.flatMap(notificationsForStudent);}
function mountBell(){let bell=document.querySelector('.efc-bell-v12');if(!bell){bell=document.createElement('button');bell.type='button';bell.className='efc-bell-v12';bell.innerHTML='<span>🔔</span><b>0</b>';bell.title='الإشعارات';bell.onclick=toggleNotifications;document.body.appendChild(bell);}refreshBell();}
