function renderNotificationPanel(panel,list){panel.innerHTML=`<div class="notification-head-v12"><b>الإشعارات</b><button class="x">×</button></div>${list.length?list.map(n=>`<button class="notification-item-v12" data-id="${esc(n.studentId)}"><b>${esc(n.studentName)}</b><span>${esc(n.message)}</span></button>`).join(''):'<div class="empty small">لا توجد تذكيرات حاليًا.</div>'}`;panel.querySelector('.x').onclick=()=>panel.hidden=true;panel.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{panel.hidden=true;openStudent(b.dataset.id,'finance');});}
setInterval(refreshBell,60000);window.addEventListener('focus',refreshBell);
async function ensurePdf(){const load=(src,key)=>new Promise((resolve,reject)=>{if(window[key])return resolve();const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>reject(new Error(`تعذر تحميل ${src}`));document.head.appendChild(s);});await Promise.all([load('./vendor/html2canvas.min.js','html2canvas'),load('./vendor/jspdf.umd.min.js','jspdf')]);}
